package com.comicsopen.web.controller;
import com.comicsopen.web.dto.Requests;import com.comicsopen.web.model.Member;import com.comicsopen.web.repository.MemberRepository;import javax.servlet.http.HttpServletRequest;import javax.servlet.http.HttpSession;import javax.validation.Valid;import org.springframework.http.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
 private final MemberRepository members;private final PasswordEncoder encoder;
 public AuthController(MemberRepository members,PasswordEncoder encoder){this.members=members;this.encoder=encoder;}
 @PostMapping("/signup") public ResponseEntity<?> signup(@Valid @RequestBody Requests.Signup input){String email=input.email().trim().toLowerCase();if(members.existsByEmail(email))return ResponseEntity.status(409).body(Map.of("error","이미 사용 중인 이메일입니다."));Member m=members.save(new Member(email,input.nickname().trim(),encoder.encode(input.password())));return ResponseEntity.status(201).body(Map.of("id",m.id,"nickname",m.nickname));}
 @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody Requests.Login input,HttpServletRequest request){Member m=members.findByEmail(input.email().trim().toLowerCase()).orElse(null);if(m==null||!encoder.matches(input.password(),m.passwordHash))return ResponseEntity.status(401).body(Map.of("error","이메일 또는 비밀번호를 확인하세요."));request.getSession();request.changeSessionId();request.getSession().setAttribute("memberId",m.id);return ResponseEntity.ok(Map.of("id",m.id,"nickname",m.nickname));}
 @GetMapping("/me") public ResponseEntity<?> me(HttpSession session){Object id=session.getAttribute("memberId");if(!(id instanceof Long))return ResponseEntity.status(401).body(Map.of("error","로그인이 필요합니다."));return members.findById((Long)id).<ResponseEntity<?>>map(m->ResponseEntity.ok(Map.of("id",m.id,"nickname",m.nickname))).orElseGet(()->ResponseEntity.status(401).body(Map.of("error","계정을 찾을 수 없습니다.")));}
 @PostMapping("/logout") public Map<String,String> logout(HttpSession session){session.invalidate();return Map.of("message","로그아웃했습니다.");}
}
